import React, { useState } from 'react';
import { addStudent } from '../api/api';

const initialForm = { name: '', roll_no: '', class: '' };

function AddStudent({ onStudentAdded }) {
  const [form, setForm] = useState(initialForm);
  const [errors, setErrors] = useState({});
  const [submitting, setSubmitting] = useState(false);
  const [serverError, setServerError] = useState(null);
  const [successMsg, setSuccessMsg] = useState(null);

  function validate() {
    const errs = {};
    if (!form.name.trim()) errs.name = 'Name is required';
    else if (!/^[a-zA-Z\s.'-]+$/.test(form.name.trim())) errs.name = 'Name must contain only letters and spaces';

    if (!form.roll_no.trim()) errs.roll_no = 'Roll number is required';

    if (!form.class.trim()) errs.class = 'Class is required';

    return errs;
  }

  function handleChange(e) {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
    setErrors(prev => ({ ...prev, [name]: undefined }));
  }

  async function handleSubmit(e) {
    e.preventDefault();
    setServerError(null);
    setSuccessMsg(null);

    const validationErrors = validate();
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0) return;

    setSubmitting(true);
    try {
      const student = await addStudent(form);
      setSuccessMsg(`${student.name} added successfully.`);
      setForm(initialForm);
      if (onStudentAdded) onStudentAdded(student);
    } catch (err) {
      setServerError(err.message);
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="card">
      <h2>Add Student</h2>
      <form onSubmit={handleSubmit} noValidate>
        <div className="form-group">
          <label htmlFor="name">Name</label>
          <input id="name" name="name" type="text" value={form.name} onChange={handleChange} placeholder="e.g. Priya Sharma" />
          {errors.name && <span className="field-error">{errors.name}</span>}
        </div>

        <div className="form-group">
          <label htmlFor="roll_no">Roll Number</label>
          <input id="roll_no" name="roll_no" type="text" value={form.roll_no} onChange={handleChange} placeholder="e.g. 2026-101" />
          {errors.roll_no && <span className="field-error">{errors.roll_no}</span>}
        </div>

        <div className="form-group">
          <label htmlFor="class">Class</label>
          <input id="class" name="class" type="text" value={form.class} onChange={handleChange} placeholder="e.g. 10th A" />
          {errors.class && <span className="field-error">{errors.class}</span>}
        </div>

        {serverError && <div className="state-message error">{serverError}</div>}
        {successMsg && <div className="state-message success">{successMsg}</div>}

        <button type="submit" className="btn-primary" disabled={submitting}>
          {submitting ? 'Adding...' : 'Add Student'}
        </button>
      </form>
    </div>
  );
}

export default AddStudent;
